from pathlib import Path
import base64, io, tarfile
EXPECTED="version: 11.6.16+176"
TARGET="version: 11.6.17+177"
PAYLOAD='[... ELLIPSIZATION ...]'
p=Path("pubspec.yaml"); s=p.read_text()
if EXPECTED not in s: raise SystemExit("V11.6.17: base version mismatch")
p.write_text(s.replace(EXPECTED,TARGET,1))
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)),mode="r:gz") as tf:
    tf.extractall(".",filter="data")
print("GardeFlow V11.6.17 redesign Medical Blue + full-screen alarm applied successfully")
